public static class RestoreAuthoredForestAndPajero
{
 const string Folder="Assets/Game/Generated/AuthoredForestPajero";
 [Serializable]public class Source{public SourceMaterial[] materials;public Part[] parts;}
 [Serializable]public class SourceMaterial{public string name;public float[] color;public float metallic,roughness;public bool transparent;}
 [Serializable]public class Part{public string name,file;public int material;public bool wheel;}
 static Material Material(SourceMaterial source,int index){var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.name="Pajero "+source.name;m.SetColor("_BaseColor",new Color(source.color[0],source.color[1],source.color[2],source.color[3]));m.SetFloat("_Smoothness",1-source.roughness);m.SetFloat("_Metallic",source.metallic);m.SetFloat("_Cull",0);if(source.transparent){m.SetFloat("_Surface",1);m.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);m.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);m.SetFloat("_ZWrite",0);m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");m.renderQueue=3000;}AssetDatabase.CreateAsset(m,Folder+"/Pajero material "+index+".mat");return m;}
 static Mesh ReadMesh(Part part){using(var reader=new BinaryReader(File.OpenRead("Assets/Game/Art/PajeroSport/"+part.file))){int count=reader.ReadInt32(),indexCount=reader.ReadInt32();var p=new Vector3[count];var n=new Vector3[count];var uv=new Vector2[count];for(int i=0;i<count;i++){p[i]=new Vector3(reader.ReadSingle(),reader.ReadSingle(),reader.ReadSingle());n[i]=new Vector3(reader.ReadSingle(),reader.ReadSingle(),reader.ReadSingle());uv[i]=new Vector2(reader.ReadSingle(),reader.ReadSingle());}var t=new int[indexCount];for(int i=0;i<t.Length;i++)t[i]=reader.ReadInt32();var mesh=new Mesh{name=part.name,indexFormat=IndexFormat.UInt32};mesh.vertices=p;mesh.normals=n;mesh.uv=uv;mesh.triangles=t;mesh.RecalculateTangents();mesh.RecalculateBounds();return mesh;}}
 static void Forest(GameObject forest)
 {
  var original=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/Art/Forest/Dirt road scene.fbx");var originals=original.GetComponentsInChildren<MeshFilter>().ToDictionary(f=>f.name);
  var alias=new Dictionary<string,string>{{"Forest_Bush","Bush_Leaves"},{"Mud_Pile","Wall_Mud"},{"Road_Edge_Gravel_Dusty","Dusty_Road_Edge_Gravel"},{"Sloped_Rock","Rock_Sloped"},{"Wood_Fence","Wooden Fence"}};
  foreach(var f in forest.GetComponentsInChildren<MeshFilter>(true))
  {
   var source=originals[f.name];var sourceMesh=source.sharedMesh;f.sharedMesh=sourceMesh;var renderer=f.GetComponent<MeshRenderer>();string sourceName=source.GetComponent<MeshRenderer>().sharedMaterial.name;
   var old=AssetDatabase.LoadAssetAtPath<Material>("Assets/Game/Generated/Forest_"+sourceName+".mat");if(old==null)throw new Exception("Missing original material "+sourceName);var m=new Material(old);m.shader=Shader.Find("Game/Living Forest");m.name="Authored "+sourceName;m.SetFloat("_SnowAmount",0);m.SetFloat("_UseWorldTextures",0);m.SetFloat("_TreeSway",0);m.SetFloat("_LeafFlutter",0);m.SetFloat("_Cull",0);
   string stem=alias.TryGetValue(sourceName,out var value)?value:sourceName;var paths=AssetDatabase.FindAssets("t:Texture2D",new[]{"Assets/Game/Art/Forest/textures"}).Select(AssetDatabase.GUIDToAssetPath).ToArray();var normal=paths.FirstOrDefault(p=>Path.GetFileNameWithoutExtension(p)==stem+"_Normal");var roughness=paths.FirstOrDefault(p=>Path.GetFileNameWithoutExtension(p)==stem+"_Roughness");if(normal!=null){var importer=(TextureImporter)AssetImporter.GetAtPath(normal);if(importer.textureType!=TextureImporterType.NormalMap){importer.textureType=TextureImporterType.NormalMap;importer.SaveAndReimport();}m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(normal));m.SetFloat("_BumpScale",.45f);}if(roughness!=null){m.SetTexture("_RoughnessMap",AssetDatabase.LoadAssetAtPath<Texture2D>(roughness));m.SetFloat("_UseRoughness",1);}else m.SetFloat("_Smoothness",sourceName.Contains("Puddle")?.6f:.13f);
   var wind=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Game/Generated/LivingForest/Living_"+f.name+".asset");if(wind==null)wind=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Game/Generated/LivingForest/"+f.name+".asset");
   // Geometry stays identical to the supplied FBX. Only optional root attributes are copied.
   if(wind!=null&&wind.vertexCount==sourceMesh.vertexCount&&wind.HasVertexAttribute(VertexAttribute.TexCoord2)){var roots=new List<Vector4>();wind.GetUVs(2,roots);if(roots.Count==sourceMesh.vertexCount){var mesh=UnityEngine.Object.Instantiate(sourceMesh);mesh.SetUVs(2,roots);AssetDatabase.CreateAsset(mesh,Folder+"/Original wind "+f.name+".asset");f.sharedMesh=mesh;m.SetFloat("_TreeSway",sourceName.Contains("Trunk")?.008f:.014f);m.SetFloat("_LeafFlutter",sourceName.Contains("Trunk")?0:.035f);}}
   AssetDatabase.CreateAsset(m,Folder+"/Forest "+sourceName+".mat");renderer.sharedMaterial=m;renderer.enabled=true;
   if(f.TryGetComponent<MeshCollider>(out var mc)){mc.sharedMesh=sourceMesh;mc.enabled=!(sourceName.Contains("Puddle")||sourceName.Contains("Vegetation")||sourceName.Contains("Leaves")||sourceName.Contains("Road_Edge"));mc.convex=false;PrefabUtility.RecordPrefabInstancePropertyModifications(mc);}PrefabUtility.RecordPrefabInstancePropertyModifications(f);PrefabUtility.RecordPrefabInstancePropertyModifications(renderer);
  }
 }
 static AudioSource Audio(Transform parent,string name,AudioClip clip,bool loop){var go=new GameObject(name);go.transform.SetParent(parent,false);go.transform.localPosition=new Vector3(0,1,.8f);var s=go.AddComponent<AudioSource>();s.clip=clip;s.loop=loop;s.playOnAwake=false;s.spatialBlend=.7f;s.minDistance=4;s.maxDistance=70;s.volume=0;return s;}
 static GameObject Pajero(ForestKamazController old)
 {
  var data=Newtonsoft.Json.JsonConvert.DeserializeObject<Source>(File.ReadAllText("Assets/Game/Art/PajeroSport/manifest.json"));var materials=data.materials.Select(Material).ToArray();var car=new GameObject("Mitsubishi Pajero Sport - supplied 2005 archive");car.transform.SetPositionAndRotation(old.transform.position,old.transform.rotation);var model=new GameObject("Original Pajero model - fixed chassis");model.transform.SetParent(car.transform,false);var body=car.AddComponent<Rigidbody>();body.mass=2050;body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;var box=car.AddComponent<BoxCollider>();box.center=new Vector3(0,1.02f,0);box.size=new Vector3(1.65f,1.3f,4.25f);
  var controller=car.AddComponent<ForestKamazController>();controller.vehicleName="MITSUBISHI PAJERO SPORT";controller.driveFrontWheels=true;controller.centreOfMass=new Vector3(0,.64f,-.05f);controller.motorTorqueNm=550;controller.wheelPowerWatts=100000;controller.maximumSpeedKmh=95;controller.lowRangeRatio=2;controller.brakeTorqueNm=2200;controller.engineBrakingNewtons=400;controller.aerodynamicDrag=.65f;controller.throttleResponseSeconds=.65f;controller.wheels=new WheelCollider[4];controller.visuals=new Transform[4];
  for(int i=0;i<4;i++){var center=new Vector3(i%2==0?-.714f:.714f,.397315f,i<2?1.51783f:-1.21340f);var collider=new GameObject("Pajero wheel collider "+i);collider.transform.SetParent(car.transform,false);collider.transform.localPosition=center;var w=collider.AddComponent<WheelCollider>();w.radius=.39731f;w.mass=35;w.suspensionDistance=.2f;var spring=w.suspensionSpring;spring.spring=45000;spring.damper=5500;spring.targetPosition=.5f;w.suspensionSpring=spring;var friction=w.forwardFriction;friction.stiffness=.9f;w.forwardFriction=friction;friction=w.sidewaysFriction;friction.stiffness=1;w.sidewaysFriction=friction;controller.wheels[i]=w;var pivot=new GameObject("Pajero wheel hub visual "+i);pivot.transform.SetParent(car.transform,false);pivot.transform.localPosition=center;controller.visuals[i]=pivot.transform;}
  var lamps=new List<Renderer>();int wheelParts=0;
  foreach(var part in data.parts){var mesh=ReadMesh(part);Transform parent=model.transform;if(part.wheel){var p=mesh.bounds.center;int axle=p.z>0?0:1;int side=p.x<0?0:1;parent=controller.visuals[axle*2+side];var v=mesh.vertices;for(int i=0;i<v.Length;i++)v[i]-=parent.localPosition;mesh.vertices=v;mesh.RecalculateBounds();wheelParts++;}AssetDatabase.CreateAsset(mesh,Folder+"/Pajero "+part.name+".asset");var go=new GameObject(part.name+" - "+data.materials[part.material].name);go.transform.SetParent(parent,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=materials[part.material];if(part.material==14)lamps.Add(r);}
  var chain=car.AddComponent<TruckChains>();chain.wheelChainVisuals=new GameObject[2];var chainMaterial=new Material(Shader.Find("Universal Render Pipeline/Lit"));chainMaterial.SetColor("_BaseColor",new Color(.22f,.25f,.28f));chainMaterial.SetFloat("_Metallic",.8f);AssetDatabase.CreateAsset(chainMaterial,Folder+"/Chain steel.mat");for(int rear=0;rear<2;rear++){var root=new GameObject("Pajero rear tire chains "+rear);root.transform.SetParent(controller.visuals[rear+2],false);for(int j=0;j<16;j++){float a=j*Mathf.PI*2/16;var link=GameObject.CreatePrimitive(PrimitiveType.Cube);UnityEngine.Object.DestroyImmediate(link.GetComponent<Collider>());link.name="Chain cross link";link.transform.SetParent(root.transform,false);link.transform.localPosition=new Vector3(0,Mathf.Cos(a)*.4f,Mathf.Sin(a)*.4f);link.transform.localRotation=Quaternion.Euler(a*Mathf.Rad2Deg,0,0);link.transform.localScale=new Vector3(.31f,.018f,.025f);link.GetComponent<Renderer>().sharedMaterial=chainMaterial;}root.SetActive(false);chain.wheelChainVisuals[rear]=root;}
  var brake=car.AddComponent<TruckBrakeLights>();brake.controller=controller;brake.lamps=lamps.ToArray();brake.lights=new Light[2];for(int i=0;i<2;i++){var g=new GameObject("Pajero brake light "+i);g.transform.SetParent(car.transform,false);g.transform.localPosition=new Vector3(i==0?-.7f:.7f,.94f,-2.18f);var light=g.AddComponent<Light>();light.type=LightType.Point;light.color=Color.red;light.intensity=1.2f;light.range=1.1f;light.enabled=false;brake.lights[i]=light;}
  var oldAudio=old.GetComponent<VehicleAudio>();if(oldAudio!=null){var profile=UnityEngine.Object.Instantiate(oldAudio.profile);profile.name="Pajero prototype audio";profile.idleRpm=750;profile.maximumRpm=4200;profile.brakeAir=null;profile.engineVolume=.22f;AssetDatabase.CreateAsset(profile,Folder+"/Pajero audio.asset");var audio=car.AddComponent<VehicleAudio>();audio.profile=profile;audio.idle=Audio(car.transform,"Pajero engine idle - prototype",profile.idle,true);audio.load=Audio(car.transform,"Pajero engine load - prototype",profile.load,true);audio.road=Audio(car.transform,"Pajero tire roll",profile.road,true);audio.slip=Audio(car.transform,"Pajero slip",profile.slip,true);audio.chains=Audio(car.transform,"Pajero chains",profile.chains,true);audio.effects=Audio(car.transform,"Pajero mechanical effects",null,false);audio.horn=Audio(car.transform,"Pajero horn - prototype",profile.horn,true);}
  return car;
 }
 public static string Main()
 {
  if(Application.isPlaying)throw new Exception("Stop Play first");string backup="Assets/Game/Scenes/BeforeAuthoredForestPajero.unity";if(File.Exists(backup)&&GameObject.Find("Mitsubishi Pajero Sport - supplied 2005 archive")!=null)throw new Exception("Already authored; inspect current scene before repeating");var scene=SceneManager.GetActiveScene();if(!File.Exists(backup))EditorSceneManager.SaveScene(scene,backup,true);Directory.CreateDirectory(Folder);AssetDatabase.Refresh();var forest=GameObject.Find("Forest - imported dirt road environment");if(!File.Exists(Folder+"/Forest Dirt_Road.mat"))Forest(forest);
  foreach(var root in scene.GetRootGameObjects()){if(root==forest)continue;if(root.name=="Continuous forest ground"||root.name=="Mountain climb stage"||root.name.Contains("10 000 km")||root.name=="Route extension entrance sign")root.SetActive(false);}
  foreach(var river in UnityEngine.Object.FindObjectsByType<RiverCurrent>())river.gameObject.SetActive(false);
  var snowfall=UnityEngine.Object.FindAnyObjectByType<LightSnowfall>();if(snowfall!=null)snowfall.gameObject.SetActive(false);
  var old=UnityEngine.Object.FindAnyObjectByType<ForestKamazController>();var car=Pajero(old);old.gameObject.SetActive(false);var camera=UnityEngine.Object.FindAnyObjectByType<DriveCamera>();camera.target=car.transform;camera.hoodOffset=new Vector3(-.35f,1.46f,.65f);camera.followDistance=8;camera.orbitYaw=0;camera.orbitPitch=18;camera.transform.position=car.transform.position-car.transform.forward*8+Vector3.up*3.8f;camera.transform.LookAt(car.transform.position+Vector3.up);
  var snowFollow=UnityEngine.Object.FindObjectsByType<LightSnowfall>(FindObjectsInactive.Include);foreach(var s in snowFollow)s.target=car.transform;
  Physics.SyncTransforms();var road=forest.GetComponentsInChildren<MeshFilter>().First(f=>f.name.EndsWith(".025"));var roadCollider=road.GetComponent<MeshCollider>();var spawn=car.transform.position;if(roadCollider.Raycast(new Ray(spawn+Vector3.up*20,Vector3.down),out var hit,50)){spawn.y=hit.point.y+.5f;car.transform.position=spawn;}
  Selection.activeGameObject=car;if(SceneView.lastActiveSceneView!=null)SceneView.lastActiveSceneView.LookAt(car.transform.position+Vector3.up,Quaternion.Euler(20,car.transform.eulerAngles.y+20,0),12);
  AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return "Restored all 26 original forest meshes/material maps; disabled procedural landscape/serpentine and altered rivers with backup. Pajero: 4 driven wheels, dedicated rim/tire groups, fixed chassis, 2050kg calibrated prototype, chains/brakes/cameras/audio connected. Backup="+backup;
 }
}

